import fs from "node:fs";
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import { VitePWA } from "vite-plugin-pwa";

// HTTPS is required for iOS Safari to allow navigator.geolocation, even on a
// local LAN IP over what would otherwise be plain HTTP. The cert/key here are
// generated by mkcert (see scripts/generate-certs.sh and README.md) so the
// browser trusts them instead of showing a self-signed-cert warning.
// server.host exposes the dev server on the LAN so it's reachable from a phone.
const certPath = "certs/dev-cert.pem";
const keyPath = "certs/dev-key.pem";

if (!fs.existsSync(certPath) || !fs.existsSync(keyPath)) {
  throw new Error(
    `Missing ${certPath}/${keyPath}. Run ./scripts/generate-certs.sh first — see README.md.`
  );
}

export default defineConfig({
  plugins: [
    react(),
    VitePWA({
      registerType: "autoUpdate",
      manifest: {
        name: "Tree Identifier",
        short_name: "TreeID",
        start_url: ".",
        display: "standalone",
        background_color: "#ffffff",
        theme_color: "#2e7d32",
        icons: [],
      },
      workbox: {
        // model.onnx is excluded from precache — it's tens of MB, well past
        // workbox's precache budget, and there's no offline-first
        // requirement here (see docs/TECH_CONTEXT.md §7). The browser's
        // normal HTTP cache still serves it after the first load.
        globPatterns: ["**/*.{js,css,html}"],
      },
    }),
  ],
  // Vite's dependency pre-bundling (esbuild) rewrites onnxruntime-web's wasm
  // reference to a .vite/deps/ path that ends up empty, overriding our
  // explicit wasmPaths config in classifier.js. Excluding it from
  // pre-bundling leaves the package's own loading logic untouched.
  optimizeDeps: {
    exclude: ["onnxruntime-web"],
  },
  server: {
    host: true,
    https: {
      cert: fs.readFileSync(certPath),
      key: fs.readFileSync(keyPath),
    },
  },
});
